CREATE TABLE "public"."colors" (
  "Id"         bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "Name"       text,
  "updated_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "colors_pkey" PRIMARY KEY ("Id")
);

ALTER TABLE "public"."colors"
  ENABLE ROW LEVEL SECURITY;

CREATE TRIGGER set_updated_at
  BEFORE UPDATE ON public.colors
  FOR EACH ROW
  EXECUTE FUNCTION public.handle_updated_at();

CREATE POLICY "Enable delete for admin only" ON "public"."colors"
  FOR DELETE
  TO PUBLIC
  USING ((public.clerk_user_role() = 'admin'::text));

CREATE POLICY "Enable insert for sales editors" ON "public"."colors"
  FOR INSERT
  TO PUBLIC
  WITH CHECK ((public.clerk_user_role() = ANY (ARRAY['admin'::text, 'designer'::text, 'scheduler'::text, 'reception'::text])));

CREATE POLICY "Enable read access for authenticated users" ON "public"."colors"
  FOR SELECT
  TO PUBLIC
  USING ((auth.role() = 'authenticated'::text));

CREATE POLICY "Enable update for sales editors" ON "public"."colors"
  FOR UPDATE
  TO PUBLIC
  USING ((public.clerk_user_role() = ANY (ARRAY['admin'::text, 'designer'::text, 'scheduler'::text, 'reception'::text])));

REVOKE ALL ON SEQUENCE "public"."colors_Id_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."colors_Id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."colors_Id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."colors_Id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."colors_Id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."colors_Id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."colors_Id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."colors_Id_seq" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."colors" TO "anon", "authenticated";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."colors" TO "service_role";

COMMENT ON TABLE "public"."colors" IS 'all colors';

REVOKE ALL ON TABLE "public"."colors" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."colors" TO "postgres";
